def check_row_balance(i, n=39):
    # A_ij = 2*i mod 3
    entry = (2 * i) % 3
    if entry == 0:
        letter = 'I'
    elif entry == 1:
        letter = 'M'
    else:
        letter = 'O'

    # Since A_ij depends only on i, all entries in row i are the same.
    return [letter] * n

# Check rows i=0, 1, 2
rows_to_check = [0, 1, 2]
results = {}
for i in rows_to_check:
    row = check_row_balance(i)
    counts = {'I': row.count('I'), 'M': row.count('M'), 'O': row.count('O')}
    results[i] = counts
    print(f"Row {i} content: {' '.join(row)}")
    print(f"Row {i} counts: {counts}")

